/**
 * "Ask an AI about OTE" — a floating button that hands the reader a ready-made prompt and opens
 * it in the assistant they pick.
 *
 * There is no API key and no backend here, on purpose: the conversation happens in the reader's
 * own account, so nobody can run up a bill that is not theirs. All this page does is build a URL.
 *
 * The prompt points the assistant at /llms.txt and /llms-full.txt, generated by
 * scripts/build-llms.mjs from the repo — spec, schemas, examples, tools and research. Nothing is
 * sent anywhere until the reader clicks an assistant, and the dialog shows the exact text first.
 *
 * Self-contained (own strings, own language detection) because every page on this site loads its
 * own script and there is no shared bundle to hang it off.
 */
(function () {
  "use strict";

  var SUPPORTED = ["en", "es"];
  var FALLBACK = "en";
  var STORAGE_KEY = "ote-lang"; // shared with every other page: pick a language once
  var SITE = "https://opentechevents.org";

  /* ---------- the prompt ---------- */

  var PROMPT = {
    en: [
      "Act as an expert on OTE Spec (OpenTechEvents), an open specification for describing and",
      "publishing tech community events.",
      "",
      "Before answering, read these sources and answer only from them:",
      "1. " + SITE + "/llms.txt — an index of every source, with a line saying what each one answers. Start here.",
      "2. " + SITE + "/llms-full.txt — the whole corpus in one file (~400 KB), if you can hold it.",
      "",
      "From the index, fetch whatever a question actually needs: the specification, the JSON",
      "Schemas, the validated examples, the tools, the changelog, and the research the spec was",
      "designed against. Say which file an answer came from.",
      "",
      "The spec is a draft (0.x) and fields can still change. If something is not in those sources,",
      "say so instead of inventing a field — an invented field is worse than no answer, because",
      "someone will publish it.",
      "",
      "Reply in the language I write in. Wait for my first question.",
    ].join("\n"),
    es: [
      "Actúa como experto en OTE Spec (OpenTechEvents), una especificación abierta para describir y",
      "publicar eventos de comunidades tecnológicas.",
      "",
      "Antes de responder, lee estas fuentes y responde solo a partir de ellas:",
      "1. " + SITE + "/llms.txt — índice de todas las fuentes, con una línea que dice qué responde cada una. Empieza aquí.",
      "2. " + SITE + "/llms-full.txt — todo el corpus en un solo fichero (~400 KB), si te cabe.",
      "",
      "Desde el índice, descarga lo que cada pregunta necesite de verdad: la especificación, los",
      "JSON Schemas, los ejemplos validados, las herramientas, el changelog y la investigación",
      "previa sobre la que se diseñó la spec. Di siempre de qué fichero sale la respuesta.",
      "",
      "La spec es un borrador (0.x) y los campos aún pueden cambiar. Si algo no está en esas",
      "fuentes, dilo en vez de inventarte un campo: un campo inventado es peor que no responder,",
      "porque alguien acabará publicándolo.",
      "",
      "Responde en el idioma en el que te escriba. Espera a mi primera pregunta.",
    ].join("\n"),
  };

  /* ---------- the assistants ---------- */

  // Every one of these takes the first message in the query string. If an assistant ever stops
  // honouring it the reader still lands on a new conversation with the prompt on the clipboard,
  // which is why "Copy" is not a secondary action here.
  var AGENTS = [
    { id: "chatgpt", name: "ChatGPT", url: function (p) { return "https://chatgpt.com/?hints=search&q=" + p; } },
    { id: "claude", name: "Claude", url: function (p) { return "https://claude.ai/new?q=" + p; } },
    { id: "perplexity", name: "Perplexity", url: function (p) { return "https://www.perplexity.ai/search?q=" + p; } },
    { id: "grok", name: "Grok", url: function (p) { return "https://grok.com/?q=" + p; } },
  ];

  /* ---------- strings ---------- */

  var STR = {
    en: {
      fab: "Ask an AI",
      fabAria: "Ask an AI about the OTE spec",
      title: "Ask an AI about OTE",
      lead: "Pick an assistant and we open a new conversation in it with the message below already written. It then reads the spec, the schemas, the examples and the research from this site before answering.",
      what: "What happens when you pick one",
      bullets: [
        "The conversation runs in <strong>your own account</strong> with that assistant. We use no API key and pay for nothing, so there is nothing to abuse.",
        "Nothing is sent from this page and nothing is logged here. The message travels in the link.",
        "The assistant needs to be able to browse the web. One that cannot will not read the spec — and may answer anyway. Check its sources.",
      ],
      promptLabel: "The message it will start with",
      copy: "Copy message",
      copied: "Copied",
      choose: "Open it in",
      close: "Close",
      hint: "It reads <a href=\"/llms.txt\">/llms.txt</a> and <a href=\"/llms-full.txt\">/llms-full.txt</a> — the whole repo, generated from the source. Paste the message anywhere else if you prefer another assistant.",
    },
    es: {
      fab: "Pregunta a una IA",
      fabAria: "Pregunta a una IA sobre la especificación OTE",
      title: "Pregunta a una IA sobre OTE",
      lead: "Elige un asistente y abrimos en él una conversación nueva con el mensaje de abajo ya escrito. A partir de ahí leerá la especificación, los esquemas, los ejemplos y la investigación de esta web antes de responder.",
      what: "Qué pasa cuando eliges uno",
      bullets: [
        "La conversación ocurre en <strong>tu propia cuenta</strong> de ese asistente. Nosotros no usamos ninguna API key ni pagamos nada, así que no hay nada que se pueda abusar.",
        "Desde esta página no se envía nada ni se registra nada. El mensaje viaja dentro del enlace.",
        "El asistente necesita poder navegar por la web. Uno que no pueda no leerá la spec — y aun así puede responder. Comprueba sus fuentes.",
      ],
      promptLabel: "El mensaje con el que empieza",
      copy: "Copiar mensaje",
      copied: "Copiado",
      choose: "Ábrelo en",
      close: "Cerrar",
      hint: "Lee <a href=\"/llms.txt\">/llms.txt</a> y <a href=\"/llms-full.txt\">/llms-full.txt</a> — todo el repositorio, generado desde el código fuente. Si prefieres otro asistente, copia el mensaje y pégalo donde quieras.",
    },
  };

  /* ---------- language ---------- */

  function pickLang() {
    var qs = new URLSearchParams(location.search).get("lang");
    if (qs && SUPPORTED.indexOf(qs) !== -1) return qs;

    var saved;
    try { saved = localStorage.getItem(STORAGE_KEY); } catch (e) { /* private mode */ }
    if (saved && SUPPORTED.indexOf(saved) !== -1) return saved;

    var prefs = navigator.languages && navigator.languages.length
      ? navigator.languages
      : [navigator.language || FALLBACK];
    for (var i = 0; i < prefs.length; i++) {
      var base = String(prefs[i]).toLowerCase().split("-")[0];
      if (SUPPORTED.indexOf(base) !== -1) return base;
    }
    return FALLBACK;
  }

  var lang = pickLang();
  var t = function () { return STR[lang]; };

  /* ---------- markup ---------- */

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = text;
    return node;
  }

  var fab = el("button", "ask-ai-fab");
  fab.type = "button";

  var dialog = el("dialog", "ask-ai-dialog");
  var heading = el("h2", "ask-ai-title");
  var lead = el("p", "ask-ai-lead");
  var whatTitle = el("h3", "ask-ai-sub");
  var bullets = el("ul", "ask-ai-list");
  var promptLabel = el("h3", "ask-ai-sub");
  var promptBox = el("pre", "ask-ai-prompt");
  var copyBtn = el("button", "btn btn-ghost ask-ai-copy");
  copyBtn.type = "button";
  var chooseTitle = el("h3", "ask-ai-sub");
  var agentRow = el("div", "ask-ai-agents");
  var hint = el("p", "ask-ai-hint");
  var closeBtn = el("button", "ask-ai-close");
  closeBtn.type = "button";

  dialog.append(closeBtn, heading, lead, whatTitle, bullets, promptLabel, promptBox, copyBtn, chooseTitle, agentRow, hint);

  function render() {
    var s = t();
    document.documentElement.lang = document.documentElement.lang || lang;

    fab.textContent = "✨ " + s.fab;
    fab.setAttribute("aria-label", s.fabAria);
    heading.textContent = s.title;
    lead.textContent = s.lead;
    whatTitle.textContent = s.what;
    promptLabel.textContent = s.promptLabel;
    promptBox.textContent = PROMPT[lang];
    copyBtn.textContent = s.copy;
    chooseTitle.textContent = s.choose;
    closeBtn.textContent = "✕";
    closeBtn.setAttribute("aria-label", s.close);
    dialog.setAttribute("aria-label", s.title);

    bullets.replaceChildren();
    s.bullets.forEach(function (line) {
      var li = document.createElement("li");
      li.innerHTML = line; // our own strings, with inline <strong> only
      bullets.appendChild(li);
    });

    hint.innerHTML = s.hint;

    agentRow.replaceChildren();
    AGENTS.forEach(function (agent) {
      var link = el("a", "btn btn-primary ask-ai-agent", agent.name);
      link.href = agent.url(encodeURIComponent(PROMPT[lang]));
      link.target = "_blank";
      link.rel = "noopener";
      link.addEventListener("click", function () { close(); });
      agentRow.appendChild(link);
    });
  }

  /* ---------- behaviour ---------- */

  function open() {
    render(); // the language may have changed since the dialog was last opened
    if (typeof dialog.showModal === "function") dialog.showModal();
    else dialog.setAttribute("open", "");
    agentRow.querySelector("a").focus();
  }

  function close() {
    if (typeof dialog.close === "function") dialog.close();
    else dialog.removeAttribute("open");
    fab.focus();
  }

  fab.addEventListener("click", open);
  closeBtn.addEventListener("click", close);

  // Clicking the backdrop closes: the dialog element itself is the full-viewport click target,
  // so a click that lands on it and not on a child came from outside the panel.
  dialog.addEventListener("click", function (event) {
    if (event.target === dialog) close();
  });

  copyBtn.addEventListener("click", function () {
    var done = function () {
      copyBtn.textContent = t().copied;
      setTimeout(function () { copyBtn.textContent = t().copy; }, 1600);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(PROMPT[lang]).then(done, function () { /* denied: leave it */ });
    } else {
      var range = document.createRange();
      range.selectNodeContents(promptBox);
      var sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
      try { document.execCommand("copy"); done(); } catch (e) { /* nothing else to try */ }
    }
  });

  // The language switcher belongs to each page's own script and fires no event we could listen
  // for, so we watch the same buttons it does.
  document.querySelectorAll(".lang button").forEach(function (btn) {
    btn.addEventListener("click", function () {
      if (SUPPORTED.indexOf(btn.dataset.lang) !== -1) {
        lang = btn.dataset.lang;
        render();
      }
    });
  });

  render();
  document.body.append(fab, dialog);
})();
